window.AUTH=window.AUTH||{};window.AUTH["08-998"]={"d":"08-998","id":"2009/08-998","n":"Hamilton v. Lanning","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae supporting respondent","date":"","url":"https://www.justice.gov/osg/media/202106/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/hamilton-v-lanning-amicus-merits","n":48}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep560/usrep560505/usrep560505.pdf","tr":true,"items":[{"t":"case","label":"Anderson v. Satterlee","cite":"21 F.3d 355","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/21/355/","op":1,"ar":1,"by":{"0":"22"}},{"t":"case","label":"Barbosa v. Solomon","cite":"235 F.3d 31","y":2000,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/235/31/","by":{"0":"20"}},{"t":"case","label":"Cannon v. University of Chicago","cite":"441 U.S. 677","y":1979,"id":"1978/77-926","sc":1,"sum":"Petitioner may maintain her lawsuit, despite the absence of any express authorization for it in Title IX.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Cohen v. de la Cruz","cite":"523 U.S. 213","y":1998,"id":"1997/96-1923","sc":1,"op":1,"sum":"The Court ruled that because Section 523(a)(2)(A) of the Bankruptcy Code excepts from discharge all liability arising from fraud, treble damages (plus attorney's fees and costs) awarded on account of the debtor's fraud fall within the scope of the exception.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Goodyear Atomic Corp. v. Miller","cite":"486 U.S. 174","y":1988,"id":"1987/86-1172","sc":1,"ar":1,"sum":"Appellee Miller, an employee of appellant at an Ohio nuclear production facility owned by the United States but operated by appellant, a private contractor, received a workers' compensation award from appellee Ohio Industrial Commission (Commission) for injuries sustained in a fall allegedly caused by a bolt protruding from the scaffold on which he was working. On the basis of a state safety regulation prohibiting …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Pennsylvania Dep’t of Pub. Welfare v. Davenport","cite":"495 U.S. 552","y":1990,"id":"1989/89-156","sc":1,"op":1,"sum":"The Code's language and structure demonstrate that restitution obligations constitute \"debts\" within the meaning of § 101(11) and are therefore dischargeable under Chapter 13.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"sum":"Authored by Justice Clarence Thomas, the Court ruled that because the term \"employees,\" as used Title VII of the Civil Rights Act of 1964, includes former employees, Robinson may sue Shell for its allegedly retaliatory post-employment actions.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Rousey v. Jacoway","cite":"544 U.S. 320","y":2005,"id":"2004/03-1407","sc":1,"sum":"The Court held that the Rouseys could exempt IRA assets from their bankruptcy estate. IRAs met both federal requirements dealing with exemptions from bankruptcy: They were \"similar plans or contracts\" to the exemptions enumerated and they \"conferred a right to receive payment on account of age.\".","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"Stellwagen v. Clum","cite":"245 U.S. 605","y":1918,"id":"scdb/1917-183","sc":1,"sum":"The Bankruptcy. Act as it was on the dates herein mentioned (February 2,1910, November 9,1910) did not operate to suspend § 6343 of the Revised Statutes of Ohio as it stood February 2, 1910, or the sections into which that section was divided and numbered by the General Code of Ohio, approved February 15, 1910, viz: §§ 11102-11105, as such sections existed May 5,1910.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"11"}},{"t":"case","label":"Williams v. United States Fid. & Guar. Co.","cite":"236 U.S. 549","y":1915,"id":"scdb/1914-235","sc":1,"sum":"Statutes should be sensibly construed, with a viewto effectuating the-legislative intent.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"11"}},{"t":"law","label":"Pub. L. No. 109-8","url":"https://www.govinfo.gov/link/plaw/109/public/8","by":{"0":"3"}},{"t":"usc","label":"11 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/11/101","subs":["(10A)(A)(i)","(10A)(A)(ii)"],"stext":{"head":"§101. Definitions","paras":[[0,"In this title the following definitions shall apply:"],[1,"(1) The term \"accountant\" means accountant authorized under applicable law to practice public accounting, and includes professional accounting association, corporation, or partnership, if so authorized."],[1,"(2) The term \"affiliate\" means—"],[2,"(A) entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(B) corporation 20 percent or more of whose outstanding voting securities are directly or indirectly owned, controlled, or held with power to vote, by the debtor, or by an entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(C) person whose business is operated under a lease or operating agreement by a debtor, or person substantially all of whose property is operated under an operating agreement with the debtor; or"],[2,"(D) entity that operates the business or substantially all of the property of the debtor under a lease or operating agreement."],[1,"(3) The term \"assisted person\" means any person whose debts consist primarily of consumer debts and the value of whose nonexempt property is less than $150,000.1"],[1,"(4) The term \"attorney\" means attorney, professional law association, corporation, or partnership, authorized under applicable law to practice law."],[1,"(4A) The term \"bankruptcy assistance\" means any goods or services sold or otherwise provided to an assisted person with the express or implied purpose of providing information, advice, counsel, document preparation, or filing, or attendance at a creditors' meeting or appearing in a case or proceeding on behalf of another or providing legal representation with respect to a case or proceeding under this title."],[1,"(5) The term \"claim\" means—"],[2,"(A) right to payment, whether or not such right is reduced to judgment, liquidated, unliquidated, fixed, contingent, matured, unmatured, disputed, undisputed, legal, equitable, secured, or unsecured; or"],[2,"(B) right to an equitable remedy for breach of performance if such breach gives rise to a right to payment, whether or not such right to an equitable remedy is reduced to judgment, fixed, contingent, matured, unmatured, disputed, undisputed, secured, or unsecured."],[1,"(6) The term \"commodity broker\" means futures commission merchant, foreign futures commission merchant, clearing organization, leverage transaction merchant, or commodity options dealer, as defined in section 761 of this title, with respect to which there is a customer, as defined in section 761 of this title."],[1,"(7) The term \"community claim\" means claim that arose before the commencement of the case concerning the debtor for which property of the kind specified in section 541(a)(2) of this title is liable, whether or not there is any such property at the time of the commencement of the case."],[1,"(7A) The term \"commercial fishing operation\" means—"],[2,"(A) the catching or harvesting of fish, shrimp, lobsters, urchins, seaweed, shellfish, or other aquatic species or products of such species; or"],[2,"(B) for purposes of section 109 and chapter 12, aquaculture activities consisting of raising for market any species or product described in subparagraph (A)."],[1,"(7B) The term \"commercial fishing vessel\" means a vessel used by a family fisherman to carry out a commercial fishing operation."],[1,"(8) The term \"consumer debt\" means debt incurred by an individual primarily for a personal, family, or household purpose."],[1,"(9) The term \"corporation\"—"],[2,"(A) includes—"],[3,"(i) association having a power or privilege that a private corporation, but not an individual or a partnership, possesses;"],[3,"(ii) partnership association organized under a law that makes only the capital subscribed responsible for the debts of such association;"],[3,"(iii) joint-stock company;"],[3,"(iv) unincorporated company or association; or"],[3,"(v) business trust; but"],[2,"(B) does not include limited partnership."],[1,"(10) The term \"creditor\" means—"],[2,"(A) entity that has a claim against the debtor that arose at the time of or before the order for relief concerning the debtor;"],[2,"(B) entity that has a claim against the estate of a kind specified in section 348(d), 502(f), 502(g), 502(h) or 502(i) of this title; or"],[2,"(C) entity that has a community claim."],[1,"(10A) The term \"current monthly income\"—"],[2,"(A) means the average monthly income from all sources that the debtor receives (or in a joint case the debtor and the debtor's spouse receive) without regard to whether such income is taxable income, derived during the 6-month period ending on—"],[3,"(i) the last day of the calendar month immediately preceding the date of the commencement of the case if the debtor files the schedule of current income required by section 521(a)(1)(B)(ii); or"],[3,"(ii) the date on which current income is determined by the court for purposes of this title if the debtor does not file the schedule of current income required by section 521(a)(1)(B)(ii); and"],[2,"(B)(i) includes any amount paid by any entity other than the debtor (or in a joint case the debtor and the debtor's spouse), on a regular basis for the household expenses of the debtor or the debtor's dependents (and in a joint case the debtor's spouse if not otherwise a dependent); and"],[2,"(ii) excludes—"],[3,"(I) benefits received under the Social Security Act (42 U.S.C. 301 et seq.);"],[3,"(II) payments to victims of war crimes or crimes against humanity on account of their status as victims of such crimes;"],[3,"(III) payments to victims of international terrorism or domestic terrorism, as those terms are defined in section 2331 of title 18, on account of their status as victims of such terrorism; and"],[3,"(IV) any monthly compensation, pension, pay, annuity, or allowance paid under title 10, 37, or 38 in connection with a disability, combat-related injury or disability, or death of a member of the uniformed services, except that any retired pay excluded under this subclause shall include retired pay paid under chapter 61 of title 10 only to the extent that such retired pay exceeds the amount of retired pay to which the debtor would otherwise be entitled if retired under any provision of title 10 other than chapter 61 of that title."],[1,"(11) The term \"custodian\" means—"],[2,"(A) receiver or trustee of any of the property of the debtor, appointed in a case or proceeding not under this title;"],[2,"(B) assignee under a general assignment for the benefit of the debtor's creditors; or"],[2,"(C) trustee, receiver, or agent under applicable law, or under a contract, that is appointed or authorized to take charge of property of the debtor for the purpose of enforcing a lien against such property, or for the purpose of general administration of such property for the benefit of the debtor's creditors."],[1,"(12) The term \"debt\" means liability on a claim."],[1,"(12A) The term \"debt relief agency\" means any person who provides any bankruptcy assistance to an assisted person in return for the payment of money or other valuable consideration, or who is a bankruptcy petition preparer under section 110, but does not include—"],[2,"(A) any person who is an officer, director, employee, or agent of a person who provides such assistance or of the bankruptcy petition preparer;"],[2,"(B) a nonprofit organization that is exempt from taxation under section 501(c)(3) of the Internal Revenue Code of 1986;"],[2,"(C) a creditor of such assisted person, to the extent that the creditor is assisting such assisted person to restructure any debt owed by such assisted person to the creditor;"],[2,"(D) a depository institution (as defined in section 3 of the Federal Deposit Insurance Act) or any Federal credit union or State credit union (as those terms are defined in section 101 of the Federal Credit Union Act), or any affiliate or subsidiary of such depository institution or credit union; or"],[2,"(E) an author, publisher, distributor, or seller of works subject to copyright protection under title 17, when acting in such capacity."],[1,"(13) The term \"debtor\" means person or municipality concerning which a case under this title has been commenced."],[1,"(13A) The term \"debtor's principal residence\"—"],[2,"(A) means a residential structure if used as the principal residence by the debtor, including incidental property, without regard to whether that structure is attached to real property; and"],[2,"(B) includes an individual condominium or cooperative unit, a mobile or manufactured home, or trailer if used as the principal residence by the debtor."],[1,"(14) The term \"disinterested person\" means a person that—"],[2,"(A) is not a creditor, an equity security holder, or an insider;"],[2,"(B) is not and was not, within 2 years before the date of the filing of the petition, a director, officer, or employee of the debtor; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/101?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§101. Definitions","tname":"Bankruptcy","by":{"0":"4, 18, 31"}},{"t":"usc","label":"11 U.S.C. § 109","url":"https://www.law.cornell.edu/uscode/text/11/109","subs":["(g)"],"by":{"0":"31"}},{"t":"usc","label":"11 U.S.C. § 307","url":"https://www.law.cornell.edu/uscode/text/11/307","by":{"0":"1"}},{"t":"usc","label":"11 U.S.C. § 362","url":"https://www.law.cornell.edu/uscode/text/11/362","subs":["(c)(3)(A)"],"stext":{"head":"§362. Automatic stay","paras":[[0,"(a) Except as provided in subsection (b) of this section, a petition filed under section 301, 302, or 303 of this title, or an application filed under section 5(a)(3) of the Securities Investor Protection Act of 1970, operates as a stay, applicable to all entities, of—"],[1,"(1) the commencement or continuation, including the issuance or employment of process, of a judicial, administrative, or other action or proceeding against the debtor that was or could have been commenced before the commencement of the case under this title, or to recover a claim against the debtor that arose before the commencement of the case under this title;"],[1,"(2) the enforcement, against the debtor or against property of the estate, of a judgment obtained before the commencement of the case under this title;"],[1,"(3) any act to obtain possession of property of the estate or of property from the estate or to exercise control over property of the estate;"],[1,"(4) any act to create, perfect, or enforce any lien against property of the estate;"],[1,"(5) any act to create, perfect, or enforce against property of the debtor any lien to the extent that such lien secures a claim that arose before the commencement of the case under this title;"],[1,"(6) any act to collect, assess, or recover a claim against the debtor that arose before the commencement of the case under this title;"],[1,"(7) the setoff of any debt owing to the debtor that arose before the commencement of the case under this title against any claim against the debtor; and"],[1,"(8) the commencement or continuation of a proceeding before the United States Tax Court concerning a tax liability of a debtor that is a corporation for a taxable period the bankruptcy court may determine or concerning the tax liability of a debtor who is an individual for a taxable period ending before the date of the order for relief under this title."],[0,"(b) The filing of a petition under section 301, 302, or 303 of this title, or of an application under section 5(a)(3) of the Securities Investor Protection Act of 1970, does not operate as a stay—"],[1,"(1) under subsection (a) of this section, of the commencement or continuation of a criminal action or proceeding against the debtor;"],[1,"(2) under subsection (a)—"],[2,"(A) of the commencement or continuation of a civil action or proceeding—"],[3,"(i) for the establishment of paternity;"],[3,"(ii) for the establishment or modification of an order for domestic support obligations;"],[3,"(iii) concerning child custody or visitation;"],[3,"(iv) for the dissolution of a marriage, except to the extent that such proceeding seeks to determine the division of property that is property of the estate; or"],[3,"(v) regarding domestic violence;"],[2,"(B) of the collection of a domestic support obligation from property that is not property of the estate;"],[2,"(C) with respect to the withholding of income that is property of the estate or property of the debtor for payment of a domestic support obligation under a judicial or administrative order or a statute;"],[2,"(D) of the withholding, suspension, or restriction of a driver's license, a professional or occupational license, or a recreational license, under State law, as specified in section 466(a)(16) of the Social Security Act;"],[2,"(E) of the reporting of overdue support owed by a parent to any consumer reporting agency as specified in section 466(a)(7) of the Social Security Act;"],[2,"(F) of the interception of a tax refund, as specified in sections 464 and 466(a)(3) of the Social Security Act or under an analogous State law; or"],[2,"(G) of the enforcement of a medical obligation, as specified under title IV of the Social Security Act;"],[1,"(3) under subsection (a) of this section, of any act to perfect, or to maintain or continue the perfection of, an interest in property to the extent that the trustee's rights and powers are subject to such perfection under section 546(b) of this title or to the extent that such act is accomplished within the period provided under section 547(e)(2)(A) of this title;"],[1,"(4) under paragraph (1), (2), (3), or (6) of subsection (a) of this section, of the commencement or continuation of an action or proceeding by a governmental unit or any organization exercising authority under the Convention on the Prohibition of the Development, Production, Stockpiling and Use of Chemical Weapons and on Their Destruction, opened for signature on January 13, 1993, to enforce such governmental unit's or organization's police and regulatory power, including the enforcement of a judgment other than a money judgment, obtained in an action or proceeding by the governmental unit to enforce such governmental unit's or organization's police or regulatory power;"],[1,"[(5) Repealed. Pub. L. 105–277, div. I, title VI, §603(1), Oct. 21, 1998, 112 Stat. 2681–866;]"],[1,"(6) under subsection (a) of this section, of the exercise by a commodity broker, forward contract merchant, stockbroker, financial institution, financial participant, or securities clearing agency of any contractual right (as defined in section 555 or 556) under any security agreement or arrangement or other credit enhancement forming a part of or related to any commodity contract, forward contract or securities contract, or of any contractual right (as defined in section 555 or 556) to offset or net out any termination value, payment amount, or other transfer obligation arising under or in connection with 1 or more such contracts, including any master agreement for such contracts;"],[1,"(7) under subsection (a) of this section, of the exercise by a repo participant or financial participant of any contractual right (as defined in section 559) under any security agreement or arrangement or other credit enhancement forming a part of or related to any repurchase agreement, or of any contractual right (as defined in section 559) to offset or net out any termination value, payment amount, or other transfer obligation arising under or in connection with 1 or more such agreements, including any master agreement for such agreements;"],[1,"(8) under subsection (a) of this section, of the commencement of any action by the Secretary of Housing and Urban Development to foreclose a mortgage or deed of trust in any case in which the mortgage or deed of trust held by the Secretary is insured or was formerly insured under the National Housing Act and covers property, or combinations of property, consisting of five or more living units;"],[1,"(9) under subsection (a), of—"],[2,"(A) an audit by a governmental unit to determine tax liability;"],[2,"(B) the issuance to the debtor by a governmental unit of a notice of tax deficiency;"],[2,"(C) a demand for tax returns; or"],[2,"(D) the making of an assessment for any tax and issuance of a notice and demand for payment of such an assessment (but any tax lien that would otherwise attach to property of the estate by reason of such an assessment shall not take effect unless such tax is a debt of the debtor that will not be discharged in the case and such property or its proceeds are transferred out of the estate to, or otherwise revested in, the debtor)."],[1,"(10) under subsection (a) of this section, of any act by a lessor to the debtor under a lease of nonresidential real property that has terminated by the expiration of the stated term of the lease before the commencement of or during a case under this title to obtain possession of such property;"],[1,"(11) under subsection (a) of this section, of the presentment of a negotiable instrument and the giving of notice of and protesting dishonor of such an instrument;"],[1,"(12) under subsection (a) of this section, after the date which is 90 days after the filing of such petition, of the commencement or continuation, and conclusion to the entry of final judgment, of an action which involves a debtor subject to reorganization pursuant to chapter 11 of this title and which was brought by the Secretary of Transportation under section 31325 of title 46 (including distribution of any proceeds of sale) to foreclose a preferred ship or fleet mortgage, or a security interest in or relating to a vessel or vessel under construction, held by the Secretary of Transportation under chapter 537 of title 46 or section 109(h) of title 49, or under applicable State law;"],[1,"(13) under subsection (a) of this section, after the date which is 90 days after the filing of such petition, of the commencement or continuation, and conclusion to the entry of final judgment, of an action which involves a debtor subject to reorganization pursuant to chapter 11 of this title and which was brought by the Secretary of Commerce under section 31325 of title 46 (including distribution of any proceeds of sale) to foreclose a preferred ship or fleet mortgage in a vessel or a mortgage, deed of trust, or other security interest in a fishing facility held by the Secretary of Commerce under chapter 537 of title 46;"],[1,"(14) under subsection (a) of this section, of any action by an accrediting agency regarding the accreditation status of the debtor as an educational institution;"],[1,"(15) under subsection (a) of this section, of any action by a State licensing body regarding the licensure of the debtor as an educational institution;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/362?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§362. Automatic stay","tname":"Bankruptcy","by":{"0":"30, 30"}},{"t":"usc","label":"11 U.S.C. § 521","url":"https://www.law.cornell.edu/uscode/text/11/521","subs":["(a)(1)(B)(ii)","(i)(1)"],"stext":{"head":"§521. Debtor's duties","paras":[[0,"(a) The debtor shall—"],[1,"(1) file—"],[2,"(A) a list of creditors; and"],[2,"(B) unless the court orders otherwise—"],[3,"(i) a schedule of assets and liabilities;"],[3,"(ii) a schedule of current income and current expenditures;"],[3,"(iii) a statement of the debtor's financial affairs and, if section 342(b) applies, a certificate—"],[4,"(I) of an attorney whose name is indicated on the petition as the attorney for the debtor, or a bankruptcy petition preparer signing the petition under section 110(b)(1), indicating that such attorney or the bankruptcy petition preparer delivered to the debtor the notice required by section 342(b); or"],[4,"(II) if no attorney is so indicated, and no bankruptcy petition preparer signed the petition, of the debtor that such notice was received and read by the debtor;"],[3,"(iv) copies of all payment advices or other evidence of payment received within 60 days before the date of the filing of the petition, by the debtor from any employer of the debtor;"],[3,"(v) a statement of the amount of monthly net income, itemized to show how the amount is calculated; and"],[3,"(vi) a statement disclosing any reasonably anticipated increase in income or expenditures over the 12-month period following the date of the filing of the petition;"],[1,"(2) if an individual debtor's schedule of assets and liabilities includes debts which are secured by property of the estate—"],[2,"(A) within thirty days after the date of the filing of a petition under chapter 7 of this title or on or before the date of the meeting of creditors, whichever is earlier, or within such additional time as the court, for cause, within such period fixes, file with the clerk a statement of his intention with respect to the retention or surrender of such property and, if applicable, specifying that such property is claimed as exempt, that the debtor intends to redeem such property, or that the debtor intends to reaffirm debts secured by such property; and"],[2,"(B) within 30 days after the first date set for the meeting of creditors under section 341(a), or within such additional time as the court, for cause, within such 30-day period fixes, perform his intention with respect to such property, as specified by subparagraph (A) of this paragraph;"],[1,"except that nothing in subparagraphs (A) and (B) of this paragraph shall alter the debtor's or the trustee's rights with regard to such property under this title, except as provided in section 362(h);"],[1,"(3) if a trustee is serving in the case or an auditor is serving under section 586(f) of title 28, cooperate with the trustee as necessary to enable the trustee to perform the trustee's duties under this title;"],[1,"(4) if a trustee is serving in the case or an auditor is serving under section 586(f) of title 28, surrender to the trustee all property of the estate and any recorded information, including books, documents, records, and papers, relating to property of the estate, whether or not immunity is granted under section 344 of this title;"],[1,"(5) appear at the hearing required under section 524(d) of this title;"],[1,"(6) in a case under chapter 7 of this title in which the debtor is an individual, not retain possession of personal property as to which a creditor has an allowed claim for the purchase price secured in whole or in part by an interest in such personal property unless the debtor, not later than 45 days after the first meeting of creditors under section 341(a), either—"],[2,"(A) enters into an agreement with the creditor pursuant to section 524(c) with respect to the claim secured by such property; or"],[2,"(B) redeems such property from the security interest pursuant to section 722; and"],[1,"(7) unless a trustee is serving in the case, continue to perform the obligations required of the administrator (as defined in section 3 of the Employee Retirement Income Security Act of 1974) of an employee benefit plan if at the time of the commencement of the case the debtor (or any entity designated by the debtor) served as such administrator."],[0,"If the debtor fails to so act within the 45-day period referred to in paragraph (6), the stay under section 362(a) is terminated with respect to the personal property of the estate or of the debtor which is affected, such property shall no longer be property of the estate, and the creditor may take whatever action as to such property as is permitted by applicable nonbankruptcy law, unless the court determines on the motion of the trustee filed before the expiration of such 45-day period, and after notice and a hearing, that such property is of consequential value or benefit to the estate, orders appropriate adequate protection of the creditor's interest, and orders the debtor to deliver any collateral in the debtor's possession to the trustee."],[0,"(b) In addition to the requirements under subsection (a), a debtor who is an individual shall file with the court—"],[1,"(1) a certificate from the approved nonprofit budget and credit counseling agency that provided the debtor services under section 109(h) describing the services provided to the debtor; and"],[1,"(2) a copy of the debt repayment plan, if any, developed under section 109(h) through the approved nonprofit budget and credit counseling agency referred to in paragraph (1)."],[0,"(c) In addition to meeting the requirements under subsection (a), a debtor shall file with the court a record of any interest that a debtor has in an education individual retirement account (as defined in section 530(b)(1) of the Internal Revenue Code of 1986), an interest in an account in a qualified ABLE program (as defined in section 529A(b) of such Code,1 or under a qualified State tuition program (as defined in section 529(b)(1) of such Code)."],[0,"(d) If the debtor fails timely to take the action specified in subsection (a)(6) of this section, or in paragraphs (1) and (2) of section 362(h), with respect to property which a lessor or bailor owns and has leased, rented, or bailed to the debtor or as to which a creditor holds a security interest not otherwise voidable under section 522(f), 544, 545, 547, 548, or 549, nothing in this title shall prevent or limit the operation of a provision in the underlying lease or agreement that has the effect of placing the debtor in default under such lease or agreement by reason of the occurrence, pendency, or existence of a proceeding under this title or the insolvency of the debtor. Nothing in this subsection shall be deemed to justify limiting such a provision in any other circumstance."],[0,"(e)(1) If the debtor in a case under chapter 7 or 13 is an individual and if a creditor files with the court at any time a request to receive a copy of the petition, schedules, and statement of financial affairs filed by the debtor, then the court shall make such petition, such schedules, and such statement available to such creditor."],[0,"(2)(A) The debtor shall provide—"],[1,"(i) not later than 7 days before the date first set for the first meeting of creditors, to the trustee a copy of the Federal income tax return required under applicable law (or at the election of the debtor, a transcript of such return) for the most recent tax year ending immediately before the commencement of the case and for which a Federal income tax return was filed; and"],[1,"(ii) at the same time the debtor complies with clause (i), a copy of such return (or if elected under clause (i), such transcript) to any creditor that timely requests such copy."],[0,"(B) If the debtor fails to comply with clause (i) or (ii) of subparagraph (A), the court shall dismiss the case unless the debtor demonstrates that the failure to so comply is due to circumstances beyond the control of the debtor."],[0,"(C) If a creditor requests a copy of such tax return or such transcript and if the debtor fails to provide a copy of such tax return or such transcript to such creditor at the time the debtor provides such tax return or such transcript to the trustee, then the court shall dismiss the case unless the debtor demonstrates that the failure to provide a copy of such tax return or such transcript is due to circumstances beyond the control of the debtor."],[0,"(3) If a creditor in a case under chapter 13 files with the court at any time a request to receive a copy of the plan filed by the debtor, then the court shall make available to such creditor a copy of the plan—"],[1,"(A) at a reasonable cost; and"],[1,"(B) not later than 7 days after such request is filed."],[0,"(f) At the request of the court, the United States trustee, or any party in interest in a case under chapter 7, 11, or 13, a debtor who is an individual shall file with the court—"],[1,"(1) at the same time filed with the taxing authority, a copy of each Federal income tax return required under applicable law (or at the election of the debtor, a transcript of such tax return) with respect to each tax year of the debtor ending while the case is pending under such chapter;"],[1,"(2) at the same time filed with the taxing authority, each Federal income tax return required under applicable law (or at the election of the debtor, a transcript of such tax return) that had not been filed with such authority as of the date of the commencement of the case and that was subsequently filed for any tax year of the debtor ending in the 3-year period ending on the date of the commencement of the case;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/521?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§521. Debtor's duties","tname":"Bankruptcy","by":{"0":"31, 31"}},{"t":"usc","label":"11 U.S.C. § 522","url":"https://www.law.cornell.edu/uscode/text/11/522","subs":["(c)"],"by":{"0":"24"}},{"t":"usc","label":"11 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/11/704","subs":["(b)(2)"],"by":{"0":"14"}},{"t":"usc","label":"11 U.S.C. § 707","url":"https://www.law.cornell.edu/uscode/text/11/707","subs":["(b)(2)"],"stext":{"head":"§707. Dismissal of a case or conversion to a case under chapter 11 or 13","paras":[[0,"(a) The court may dismiss a case under this chapter only after notice and a hearing and only for cause, including—"],[1,"(1) unreasonable delay by the debtor that is prejudicial to creditors;"],[1,"(2) nonpayment of any fees or charges required under chapter 123 of title 28; and"],[1,"(3) failure of the debtor in a voluntary case to file, within fifteen days or such additional time as the court may allow after the filing of the petition commencing such case, the information required by paragraph (1) of section 521(a), but only on a motion by the United States trustee."],[0,"(b)(1) After notice and a hearing, the court, on its own motion or on a motion by the United States trustee, trustee (or bankruptcy administrator, if any), or any party in interest, may dismiss a case filed by an individual debtor under this chapter whose debts are primarily consumer debts, or, with the debtor's consent, convert such a case to a case under chapter 11 or 13 of this title, if it finds that the granting of relief would be an abuse of the provisions of this chapter. In making a determination whether to dismiss a case under this section, the court may not take into consideration whether a debtor has made, or continues to make, charitable contributions (that meet the definition of \"charitable contribution\" under section 548(d)(3)) to any qualified religious or charitable entity or organization (as that term is defined in section 548(d)(4))."],[0,"(2)(A)(i) In considering under paragraph (1) whether the granting of relief would be an abuse of the provisions of this chapter, the court shall presume abuse exists if the debtor's current monthly income reduced by the amounts determined under clauses (ii), (iii), and (iv), and multiplied by 60 is not less than the lesser of—"],[1,"(I) 25 percent of the debtor's nonpriority unsecured claims in the case, or $6,000,1 whichever is greater; or"],[1,"(II) $10,000.1"],[0,"(ii)(I) The debtor's monthly expenses shall be the debtor's applicable monthly expense amounts specified under the National Standards and Local Standards, and the debtor's actual monthly expenses for the categories specified as Other Necessary Expenses issued by the Internal Revenue Service for the area in which the debtor resides, as in effect on the date of the order for relief, for the debtor, the dependents of the debtor, and the spouse of the debtor in a joint case, if the spouse is not otherwise a dependent. Such expenses shall include reasonably necessary health insurance, disability insurance, and health savings account expenses for the debtor, the spouse of the debtor, or the dependents of the debtor. Notwithstanding any other provision of this clause, the monthly expenses of the debtor shall not include any payments for debts. In addition, the debtor's monthly expenses shall include the debtor's reasonably necessary expenses incurred to maintain the safety of the debtor and the family of the debtor from family violence as identified under section 302 of the Family Violence Prevention and Services Act, or other applicable Federal law. The expenses included in the debtor's monthly expenses described in the preceding sentence shall be kept confidential by the court. In addition, if it is demonstrated that it is reasonable and necessary, the debtor's monthly expenses may also include an additional allowance for food and clothing of up to 5 percent of the food and clothing categories as specified by the National Standards issued by the Internal Revenue Service."],[0,"(II) In addition, the debtor's monthly expenses may include, if applicable, the continuation of actual expenses paid by the debtor that are reasonable and necessary for care and support of an elderly, chronically ill, or disabled household member or member of the debtor's immediate family (including parents, grandparents, siblings, children, and grandchildren of the debtor, the dependents of the debtor, and the spouse of the debtor in a joint case who is not a dependent) and who is unable to pay for such reasonable and necessary expenses. Such monthly expenses may include, if applicable, contributions to an account of a qualified ABLE program to the extent such contributions are not excess contributions (as described in section 4973(h) of the Internal Revenue Code of 1986) and if the designated beneficiary of such account is a child, stepchild, grandchild, or stepgrandchild of the debtor."],[0,"(III) In addition, for a debtor eligible for chapter 13, the debtor's monthly expenses may include the actual administrative expenses of administering a chapter 13 plan for the district in which the debtor resides, up to an amount of 10 percent of the projected plan payments, as determined under schedules issued by the Executive Office for United States Trustees."],[0,"(IV) In addition, the debtor's monthly expenses may include the actual expenses for each dependent child less than 18 years of age, not to exceed $1,500 1 per year per child, to attend a private or public elementary or secondary school if the debtor provides documentation of such expenses and a detailed explanation of why such expenses are reasonable and necessary, and why such expenses are not already accounted for in the National Standards, Local Standards, or Other Necessary Expenses referred to in subclause (I)."],[0,"(V) In addition, the debtor's monthly expenses may include an allowance for housing and utilities, in excess of the allowance specified by the Local Standards for housing and utilities issued by the Internal Revenue Service, based on the actual expenses for home energy costs if the debtor provides documentation of such actual expenses and demonstrates that such actual expenses are reasonable and necessary."],[0,"(iii) The debtor's average monthly payments on account of secured debts shall be calculated as the sum of—"],[1,"(I) the total of all amounts scheduled as contractually due to secured creditors in each month of the 60 months following the date of the filing of the petition; and"],[1,"(II) any additional payments to secured creditors necessary for the debtor, in filing a plan under chapter 13 of this title, to maintain possession of the debtor's primary residence, motor vehicle, or other property necessary for the support of the debtor and the debtor's dependents, that serves as collateral for secured debts;"],[0,"divided by 60."],[0,"(iv) The debtor's expenses for payment of all priority claims (including priority child support and alimony claims) shall be calculated as the total amount of debts entitled to priority, divided by 60."],[0,"(B)(i) In any proceeding brought under this subsection, the presumption of abuse may only be rebutted by demonstrating special circumstances, such as a serious medical condition or a call or order to active duty in the Armed Forces, to the extent such special circumstances that justify additional expenses or adjustments of current monthly income for which there is no reasonable alternative."],[0,"(ii) In order to establish special circumstances, the debtor shall be required to itemize each additional expense or adjustment of income and to provide—"],[1,"(I) documentation for such expense or adjustment to income; and"],[1,"(II) a detailed explanation of the special circumstances that make such expenses or adjustment to income necessary and reasonable."],[0,"(iii) The debtor shall attest under oath to the accuracy of any information provided to demonstrate that additional expenses or adjustments to income are required."],[0,"(iv) The presumption of abuse may only be rebutted if the additional expenses or adjustments to income referred to in clause (i) cause the product of the debtor's current monthly income reduced by the amounts determined under clauses (ii), (iii), and (iv) of subparagraph (A) when multiplied by 60 to be less than the lesser of—"],[1,"(I) 25 percent of the debtor's nonpriority unsecured claims, or $6,000,1 whichever is greater; or"],[1,"(II) $10,000.1"],[0,"(C) As part of the schedule of current income and expenditures required under section 521, the debtor shall include a statement of the debtor's current monthly income, and the calculations that determine whether a presumption arises under subparagraph (A)(i), that show how each such amount is calculated."],[0,"(D) Subparagraphs (A) through (C) shall not apply, and the court may not dismiss or convert a case based on any form of means testing—"],[1,"(i) if the debtor is a disabled veteran (as defined in section 3741(1) of title 38), and the indebtedness occurred primarily during a period during which he or she was—"],[2,"(I) on active duty (as defined in section 101(d)(1) of title 10); or"],[2,"(II) performing a homeland defense activity (as defined in section 901(1) of title 32); or"],[1,"(ii) with respect to the debtor, while the debtor is—"],[2,"(I) on, and during the 540-day period beginning immediately after the debtor is released from, a period of active duty (as defined in section 101(d)(1) of title 10) of not less than 90 days; or"],[2,"(II) performing, and during the 540-day period beginning immediately after the debtor is no longer performing, a homeland defense activity (as defined in section 901(1) of title 32) performed for a period of not less than 90 days;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/707?type=usc&year=mostrecent&link-type=html"},"op":4,"ar":1,"head":"§707. Dismissal of a case or conversion to a case under chapter 11 or 13","tname":"Bankruptcy","by":{"0":"5, 6"}},{"t":"usc","label":"11 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/11/1301","by":{"0":"2"}},{"t":"usc","label":"11 U.S.C. § 1306","url":"https://www.law.cornell.edu/uscode/text/11/1306","subs":["(b)"],"by":{"0":"2"}},{"t":"usc","label":"11 U.S.C. § 1321","url":"https://www.law.cornell.edu/uscode/text/11/1321","by":{"0":"2"}},{"t":"usc","label":"11 U.S.C. § 1322","url":"https://www.law.cornell.edu/uscode/text/11/1322","subs":["(d)(1)","(d)(2)"],"by":{"0":"12, 14, 14"}},{"t":"usc","label":"11 U.S.C. § 1323","url":"https://www.law.cornell.edu/uscode/text/11/1323","by":{"0":"19"}},{"t":"usc","label":"11 U.S.C. § 1324","url":"https://www.law.cornell.edu/uscode/text/11/1324","by":{"0":"1"}},{"t":"usc","label":"11 U.S.C. § 1325","url":"https://www.law.cornell.edu/uscode/text/11/1325","subs":["(a)(6)","(a)(7)","(b)(1)(A)","(b)(1)(B)","(b)(2)","(b)(2)(A)(2000)","(b)(2)(A)(i)","(b)(2)(A)(ii)","(b)(2)(B)","(b)(2)(B)(2000)","(b)(3)","(b)(3)(A)","(b)(4)(A)(ii)"],"stext":{"head":"§1325. Confirmation of plan","paras":[[0,"(a) Except as provided in subsection (b), the court shall confirm a plan if—"],[1,"(1) The plan complies with the provisions of this chapter and with the other applicable provisions of this title;"],[1,"(2) any fee, charge, or amount required under chapter 123 of title 28, or by the plan, to be paid before confirmation, has been paid;"],[1,"(3) the plan has been proposed in good faith and not by any means forbidden by law;"],[1,"(4) the value, as of the effective date of the plan, of property to be distributed under the plan on account of each allowed unsecured claim is not less than the amount that would be paid on such claim if the estate of the debtor were liquidated under chapter 7 of this title on such date;"],[1,"(5) with respect to each allowed secured claim provided for by the plan—"],[2,"(A) the holder of such claim has accepted the plan;"],[2,"(B)(i) the plan provides that—"],[3,"(I) the holder of such claim retain the lien securing such claim until the earlier of—"],[4,"(aa) the payment of the underlying debt determined under nonbankruptcy law; or"],[4,"(bb) discharge under section 1328; and"],[3,"(II) if the case under this chapter is dismissed or converted without completion of the plan, such lien shall also be retained by such holder to the extent recognized by applicable nonbankruptcy law;"],[2,"(ii) the value, as of the effective date of the plan, of property to be distributed under the plan on account of such claim is not less than the allowed amount of such claim; and"],[2,"(iii) if—"],[3,"(I) property to be distributed pursuant to this subsection is in the form of periodic payments, such payments shall be in equal monthly amounts; and"],[3,"(II) the holder of the claim is secured by personal property, the amount of such payments shall not be less than an amount sufficient to provide to the holder of such claim adequate protection during the period of the plan; or"],[2,"(C) the debtor surrenders the property securing such claim to such holder;"],[1,"(6) the debtor will be able to make all payments under the plan and to comply with the plan;"],[1,"(7) the action of the debtor in filing the petition was in good faith;"],[1,"(8) the debtor has paid all amounts that are required to be paid under a domestic support obligation and that first become payable after the date of the filing of the petition if the debtor is required by a judicial or administrative order, or by statute, to pay such domestic support obligation; and"],[1,"(9) the debtor has filed all applicable Federal, State, and local tax returns as required by section 1308."],[0,"For purposes of paragraph (5), section 506 shall not apply to a claim described in that paragraph if the creditor has a purchase money security interest securing the debt that is the subject of the claim, the debt was incurred within the 910-day period preceding the date of the filing of the petition, and the collateral for that debt consists of a motor vehicle (as defined in section 30102 of title 49) acquired for the personal use of the debtor, or if collateral for that debt consists of any other thing of value, if the debt was incurred during the 1-year period preceding that filing."],[0,"(b)(1) If the trustee or the holder of an allowed unsecured claim objects to the confirmation of the plan, then the court may not approve the plan unless, as of the effective date of the plan—"],[1,"(A) the value of the property to be distributed under the plan on account of such claim is not less than the amount of such claim; or"],[1,"(B) the plan provides that all of the debtor's projected disposable income to be received in the applicable commitment period beginning on the date that the first payment is due under the plan will be applied to make payments to unsecured creditors under the plan."],[0,"(2) For purposes of this subsection, the term \"disposable income\" means current monthly income received by the debtor (other than child support payments, foster care payments, or disability payments for a dependent child made in accordance with applicable nonbankruptcy law to the extent reasonably necessary to be expended for such child) less amounts reasonably necessary to be expended—"],[1,"(A)(i) for the maintenance or support of the debtor or a dependent of the debtor, or for a domestic support obligation, that first becomes payable after the date the petition is filed; and"],[1,"(ii) for charitable contributions (that meet the definition of \"charitable contribution\" under section 548(d)(3)) to a qualified religious or charitable entity or organization (as defined in section 548(d)(4)) in an amount not to exceed 15 percent of gross income of the debtor for the year in which the contributions are made; and"],[1,"(B) if the debtor is engaged in business, for the payment of expenditures necessary for the continuation, preservation, and operation of such business."],[0,"(3) Amounts reasonably necessary to be expended under paragraph (2), other than subparagraph (A)(ii) of paragraph (2), shall be determined in accordance with subparagraphs (A) and (B) of section 707(b)(2), if the debtor has current monthly income, when multiplied by 12, greater than—"],[1,"(A) in the case of a debtor in a household of 1 person, the median family income of the applicable State for 1 earner;"],[1,"(B) in the case of a debtor in a household of 2, 3, or 4 individuals, the highest median family income of the applicable State for a family of the same number or fewer individuals; or"],[1,"(C) in the case of a debtor in a household exceeding 4 individuals, the highest median family income of the applicable State for a family of 4 or fewer individuals, plus $525 1 per month for each individual in excess of 4."],[0,"(4) For purposes of this subsection, the \"applicable commitment period\"—"],[1,"(A) subject to subparagraph (B), shall be—"],[2,"(i) 3 years; or"],[2,"(ii) not less than 5 years, if the current monthly income of the debtor and the debtor's spouse combined, when multiplied by 12, is not less than—"],[3,"(I) in the case of a debtor in a household of 1 person, the median family income of the applicable State for 1 earner;"],[3,"(II) in the case of a debtor in a household of 2, 3, or 4 individuals, the highest median family income of the applicable State for a family of the same number or fewer individuals; or"],[3,"(III) in the case of a debtor in a household exceeding 4 individuals, the highest median family income of the applicable State for a family of 4 or fewer individuals, plus $525 1 per month for each individual in excess of 4; and"],[1,"(B) may be less than 3 or 5 years, whichever is applicable under subparagraph (A), but only if the plan provides for payment in full of all allowed unsecured claims over a shorter period."],[0,"(c) After confirmation of a plan, the court may order any entity from whom the debtor receives income to pay all or any part of such income to the trustee."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1325?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§1325. Confirmation of plan","tname":"Bankruptcy","by":{"0":"passim, 17, 26, 29, 2, passim, 4, 5, 18, 3, 5, 5, 5, 3, 14, 18, 5, 14"}},{"t":"usc","label":"11 U.S.C. § 1326","url":"https://www.law.cornell.edu/uscode/text/11/1326","subs":["(b)(3)(B)(ii)"],"by":{"0":"14"}},{"t":"usc","label":"11 U.S.C. § 1327","url":"https://www.law.cornell.edu/uscode/text/11/1327","subs":["(a)"],"by":{"0":"17, 20"}},{"t":"usc","label":"11 U.S.C. § 1329","url":"https://www.law.cornell.edu/uscode/text/11/1329","by":{"0":"19, 20"}},{"t":"usc","label":"28 U.S.C. § 586","url":"https://www.law.cornell.edu/uscode/text/28/586","subs":["(a)(3)(C)"],"stext":{"head":"§586. Duties; supervision by Attorney General","paras":[[0,"(a) Each United States trustee, within the region for which such United States trustee is appointed, shall—"],[1,"(1) establish, maintain, and supervise a panel of private trustees that are eligible and available to serve as trustees in cases under chapter 7 of title 11;"],[1,"(2) serve as and perform the duties of a trustee in a case under title 11 when required under title 11 to serve as trustee in such a case;"],[1,"(3) supervise the administration of cases and trustees in cases under chapter 7, 11 (including subchapter V of chapter 11), 12, 13, or 15 of title 11 by, whenever the United States trustee considers it to be appropriate—"],[2,"(A)(i) reviewing, in accordance with procedural guidelines adopted by the Executive Office of the United States Trustee (which guidelines shall be applied uniformly by the United States trustee except when circumstances warrant different treatment), applications filed for compensation and reimbursement under section 330 of title 11; and"],[2,"(ii) filing with the court comments with respect to such application and, if the United States Trustee considers it to be appropriate, objections to such application;"],[2,"(B) monitoring plans and disclosure statements filed in cases under chapter 11 of title 11 and filing with the court, in connection with hearings under sections 1125 and 1128 of such title, comments with respect to such plans and disclosure statements;"],[2,"(C) monitoring plans filed under chapters 12 and 13 of title 11 and filing with the court, in connection with hearings under sections 1224, 1229, 1324, and 1329 of such title, comments with respect to such plans;"],[2,"(D) taking such action as the United States trustee deems to be appropriate to ensure that all reports, schedules, and fees required to be filed under title 11 and this title by the debtor are properly and timely filed;"],[2,"(E) monitoring creditors' committees appointed under title 11;"],[2,"(F) notifying the appropriate United States attorney of matters which relate to the occurrence of any action which may constitute a crime under the laws of the United States and, on the request of the United States attorney, assisting the United States attorney in carrying out prosecutions based on such action;"],[2,"(G) monitoring the progress of cases under title 11 and taking such actions as the United States trustee deems to be appropriate to prevent undue delay in such progress;"],[2,"(H) in small business cases (as defined in section 101 of title 11), performing the additional duties specified in title 11 pertaining to such cases; and"],[2,"(I) monitoring applications filed under section 327 of title 11 and, whenever the United States trustee deems it to be appropriate, filing with the court comments with respect to the approval of such applications;"],[1,"(4) deposit or invest under section 345 of title 11 money received as trustee in cases under title 11;"],[1,"(5) perform the duties prescribed for the United States trustee under title 11 and this title, and such duties consistent with title 11 and this title as the Attorney General may prescribe;"],[1,"(6) make such reports as the Attorney General directs, including the results of audits performed under section 603(a) of the Bankruptcy Abuse Prevention and Consumer Protection Act of 2005;"],[1,"(7) in each of such small business cases—"],[2,"(A) conduct an initial debtor interview as soon as practicable after the date of the order for relief but before the first meeting scheduled under section 341(a) of title 11, at which time the United States trustee shall—"],[3,"(i) begin to investigate the debtor's viability;"],[3,"(ii) inquire about the debtor's business plan;"],[3,"(iii) explain the debtor's obligations to file monthly operating reports and other required reports;"],[3,"(iv) attempt to develop an agreed scheduling order; and"],[3,"(v) inform the debtor of other obligations;"],[2,"(B) if determined to be appropriate and advisable, visit the appropriate business premises of the debtor, ascertain the state of the debtor's books and records, and verify that the debtor has filed its tax returns; and"],[2,"(C) review and monitor diligently the debtor's activities, to determine as promptly as possible whether the debtor will be unable to confirm a plan; and"],[1,"(8) in any case in which the United States trustee finds material grounds for any relief under section 1112 of title 11, apply promptly after making that finding to the court for relief."],[0,"(b) If the number of cases under subchapter V of chapter 11 or chapter 12 or 13 of title 11 commenced in a particular region so warrants, the United States trustee for such region may, subject to the approval of the Attorney General, appoint one or more individuals to serve as standing trustee, or designate one or more assistant United States trustees to serve in cases under such chapter. The United States trustee for such region shall supervise any such individual appointed as standing trustee in the performance of the duties of standing trustee."],[0,"(c) Each United States trustee shall be under the general supervision of the Attorney General, who shall provide general coordination and assistance to the United States trustees."],[0,"(d)(1) The Attorney General shall prescribe by rule qualifications for membership on the panels established by United States trustees under paragraph (a)(1) of this section, and qualifications for appointment under subsection (b) of this section to serve as standing trustee in cases under subchapter V of chapter 11 or chapter 12 or 13 of title 11. The Attorney General may not require that an individual be an attorney in order to qualify for appointment under subsection (b) of this section to serve as standing trustee in cases under subchapter V of chapter 11 or chapter 12 or 13 of title 11."],[0,"(2) A trustee whose appointment under subsection (a)(1) or under subsection (b) is terminated or who ceases to be assigned to cases filed under title 11, United States Code, may obtain judicial review of the final agency decision by commencing an action in the district court of the United States for the district for which the panel to which the trustee is appointed under subsection (a)(1), or in the district court of the United States for the district in which the trustee is appointed under subsection (b) resides, after first exhausting all available administrative remedies, which if the trustee so elects, shall also include an administrative hearing on the record. Unless the trustee elects to have an administrative hearing on the record, the trustee shall be deemed to have exhausted all administrative remedies for purposes of this paragraph if the agency fails to make a final agency decision within 90 days after the trustee requests administrative remedies. The Attorney General shall prescribe procedures to implement this paragraph. The decision of the agency shall be affirmed by the district court unless it is unreasonable and without cause based on the administrative record before the agency."],[0,"(e)(1) The Attorney General, after consultation with a United States trustee that has appointed an individual under subsection (b) of this section to serve as standing trustee in cases under subchapter V of chapter 11 or chapter 12 or 13 of title 11, shall fix—"],[1,"(A) a maximum annual compensation for such individual consisting of—"],[2,"(i) an amount not to exceed the highest annual rate of basic pay in effect for level V of the Executive Schedule; and"],[2,"(ii) the cash value of employment benefits comparable to the employment benefits provided by the United States to individuals who are employed by the United States at the same rate of basic pay to perform similar services during the same period of time; and"],[1,"(B) a percentage fee not to exceed—"],[2,"(i) in the case of a debtor who is not a family farmer, ten percent; or"],[2,"(ii) in the case of a debtor who is a family farmer, the sum of—"],[3,"(I) not to exceed ten percent of the payments made under the plan of such debtor, with respect to payments in an aggregate amount not to exceed $450,000; and"],[3,"(II) three percent of payments made under the plan of such debtor, with respect to payments made after the aggregate amount of payments made under the plan exceeds $450,000;"],[1,"based on such maximum annual compensation and the actual, necessary expenses incurred by such individual as standing trustee."],[0,"(2) Such individual shall collect such percentage fee from all payments received by such individual under plans in the cases under subchapter V of chapter 11 or chapter 12 or 13 of title 11 for which such individual serves as standing trustee. Such individual shall pay to the United States trustee, and the United States trustee shall deposit in the United States Trustee System Fund—"],[1,"(A) any amount by which the actual compensation of such individual exceeds 5 per centum upon all payments received under plans in cases under subchapter V of chapter 11 or chapter 12 or 13 of title 11 for which such individual serves as standing trustee; and"],[1,"(B) any amount by which the percentage for all such cases exceeds—"],[2,"(i) such individual's actual compensation for such cases, as adjusted under subparagraph (A) of paragraph (1); plus"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/586?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§586. Duties; supervision by Attorney General","tname":"Judiciary and Judicial Procedure","by":{"0":"1"}}]};